     1	package hotel.reservations;
     2	
     3	import java.util.List;
     4	import java.util.Optional;
     5	import java.util.function.Function;
     6	
     7	/** Turns the identification fields into the one kind of identification they describe. */
     8	public final class Identifications {
     9	
    10	    /** Every kind of identification; a new kind is one more entry here. */
    11	    private static final List<Function<IdentificationFields, Optional<Identification>>> KINDS =
    12	            List.of(Cpf::from, Company::from, ForeignGuest::from);
    13	
    14	    private Identifications() {
    15	    }
    16	
    17	    public static Identification from(IdentificationFields fields) {
    18	        List<Identification> found = KINDS.stream()
    19	                .map(kind -> kind.apply(fields))
    20	                .flatMap(Optional::stream)
    21	                .toList();
    22	        if (found.size() != 1) {
    23	            throw new HotelException(
    24	                    ErrorCode.INVALID_REQUEST,
    25	                    "identify the guest with exactly one of: guestCpf; companyCnpj and companyName; "
    26	                            + "guestPassport and guestCountry");
    27	        }
    28	        return found.get(0);
    29	    }
    30	
    31	    public static IdentificationFields fieldsOf(Identification identification) {
    32	        return new IdentificationFields(
    33	                identification.cpf(),
    34	                identification.companyCnpj(),
    35	                identification.companyName(),
    36	                identification.passport(),
    37	                identification.country());
    38	    }
    39	}
