    20	    }
    21	
    22	    public final ReservationReceipt issue(Reservation reservation, Room room) {
    23	        Identification identification = reservation.guest().identification();
    24	        Price price = reservation.price();
    25	        return new ReservationReceipt(
    26	                title(),
    27	                reservation.id(),
    28	                reservation.guest().name(),
    29	                identification.cpf(),
    30	                identification.companyCnpj(),
    31	                identification.companyName(),
    32	                identification.passport(),
    33	                identification.country(),
    34	                room.number(),
    35	                room.type(),
    36	                reservation.checkIn(),
    37	                reservation.checkOut(),
    38	                price.nights(),
    39	                price.subtotal(),
    40	                price.discount(),
    41	                price.total(),
    42	                text(reservation, room));
    43	    }
    44	
    45	    abstract String title();
    46	
    47	    /** The lines that say who the document is for. */
    48	    abstract List<String> partyLines(Reservation reservation);
    49	
    50	    /** What comes after the total. */
    51	    List<String> closingLines(Price price) {
    52	        return List.of();
    53	    }
    54	
    55	    final String guestLine(Reservation reservation, String identity) {
    56	        return wording.guest() + ": " + reservation.guest().name() + " (" + identity + ")";
    57	    }
    58	
    59	    final Wording wording() {
    60	        return wording;
    61	    }
    62	
    63	    private String text(Reservation reservation, Room room) {
    64	        Price price = reservation.price();
    65	        List<String> lines = new ArrayList<>();
    66	        lines.add(title() + " " + wording.numberSign() + " " + reservation.id());
    67	        lines.addAll(partyLines(reservation));
    68	        lines.add(wording.room() + ": " + room.number() + " (" + room.type() + ")");
    69	        lines.add(wording.checkIn() + ": " + wording.date(reservation.checkIn())
    70	                + " | " + wording.checkOut() + ": " + wording.date(reservation.checkOut())
    71	                + " | " + wording.nights(price.nights()));
    72	        lines.add(wording.subtotal() + ": " + wording.money(price.subtotal()));
    73	        if (price.discount().signum() > 0) {
    74	            lines.add(wording.discount() + ": " + wording.money(price.discount()));
    75	        }
    76	        lines.add(wording.total() + ": " + wording.money(price.total()));
    77	        lines.addAll(closingLines(price));
    78	        return String.join("\n", lines) + "\n";
    79	    }
    80	}
