157	/** Keeps the reservations in the database. */
158	public final class ReservationStore {
159	
160	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name, "
161	            + "guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights, subtotal, discount, "
162	            + "total, status, amount_paid, refund";
163	    /** PostgreSQL's code for a broken exclusion constraint: here, the room was already booked on one of the nights. */
164	    private static final String EXCLUSION_VIOLATION = "23P01";
165	
166	    private final DataSource dataSource;
167	
168	    public ReservationStore(DataSource dataSource) {
169	        this.dataSource = dataSource;
170	    }
171	
172	    /** Saves a new reservation; the database numbers it. */
173	    Reservation add(NewReservation request, Price price) {
174	        String insert = "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, company_cnpj, "
175	                + "company_name, guest_passport, guest_country, check_in, "
176	                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid) "
177	                + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING id";
178	        try (Connection connection = dataSource.getConnection();
179	                PreparedStatement statement = connection.prepareStatement(insert)) {
180	            statement.setInt(1, request.roomNumber());
181	            statement.setString(2, request.guest().name());
182	            statement.setString(3, request.guest().email());
183	            IdentificationFields identification = Identifications.fieldsOf(request.guest().identification());
184	            statement.setString(4, identification.cpf());
185	            statement.setString(5, identification.cnpj());
186	            statement.setString(6, identification.companyName());
187	            statement.setString(7, identification.passport());
188	            statement.setString(8, identification.country());
189	            statement.setDate(9, Date.valueOf(request.checkIn()));
190	            statement.setDate(10, Date.valueOf(request.checkOut()));
191	            statement.setInt(11, request.guests());
192	            statement.setString(12, request.ratePlan().name());
193	            statement.setInt(13, price.nights());
194	            statement.setBigDecimal(14, price.subtotal());
195	            statement.setBigDecimal(15, price.discount());
196	            statement.setBigDecimal(16, price.total());
197	            statement.setString(17, ReservationStatus.PENDING.name());
198	            statement.setBigDecimal(18, PriceCalculator.cents(BigDecimal.ZERO));
199	            try (ResultSet generated = statement.executeQuery()) {
200	                generated.next();
201	                return new Reservation(generated.getLong("id"), request, price);
202	            }
203	        } catch (SQLException failure) {
204	            if (EXCLUSION_VIOLATION.equals(failure.getSQLState())) {
205	                throw new HotelException(ErrorCode.ROOM_UNAVAILABLE,
206	                        "room " + request.roomNumber() + " is taken on some of those nights");
207	            }
208	            throw new IllegalStateException("could not save the reservation", failure);
209	        }
210	    }
211	
212	    /** Saves what changes in a reservation's life: the status, what was paid and what went back. */
213	    void update(Reservation reservation) {
214	        try (Connection connection = dataSource.getConnection();
215	                PreparedStatement statement = connection.prepareStatement(
216	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
217	            statement.setString(1, reservation.status().name());
218	            statement.setBigDecimal(2, reservation.amountPaid());
219	            statement.setBigDecimal(3, reservation.refund());
220	            statement.setLong(4, reservation.id());
221	            statement.executeUpdate();
222	        } catch (SQLException failure) {
223	            throw new IllegalStateException("could not save reservation " + reservation.id(), failure);
224	        }
225	    }
226	
227	    /** Whether a reservation that was not cancelled holds the room on any of the nights. */
228	    boolean isRoomTaken(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
229	        try (Connection connection = dataSource.getConnection();
230	                PreparedStatement select = connection.prepareStatement(
231	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
232	                                + "AND check_in < ? AND ? < check_out")) {
233	            select.setInt(1, roomNumber);
234	            select.setDate(2, Date.valueOf(checkOut));
235	            select.setDate(3, Date.valueOf(checkIn));
236	            try (ResultSet rows = select.executeQuery()) {
237	                return rows.next();
238	            }
239	        } catch (SQLException failure) {
240	            throw new IllegalStateException("could not check room " + roomNumber, failure);
241	        }
242	    }
243	
244	    public Optional<Reservation> find(long id) {
245	        try (Connection connection = dataSource.getConnection();
246	                PreparedStatement select = connection.prepareStatement(
247	                        "SELECT " + COLUMNS + " FROM reservations WHERE id = ?")) {
248	            select.setLong(1, id);
249	            try (ResultSet rows = select.executeQuery()) {
250	                return rows.next() ? Optional.of(read(rows)) : Optional.empty();
251	            }
252	        } catch (SQLException failure) {
253	            throw new IllegalStateException("could not read reservation " + id, failure);
254	        }
255	    }
256	
257	    public List<Reservation> all() {
258	        try (Connection connection = dataSource.getConnection();
259	                PreparedStatement select = connection.prepareStatement(
260	                        "SELECT " + COLUMNS + " FROM reservations ORDER BY id");
261	                ResultSet rows = select.executeQuery()) {
262	            List<Reservation> reservations = new ArrayList<>();
263	            while (rows.next()) {
264	                reservations.add(read(rows));
265	            }
266	            return reservations;
267	        } catch (SQLException failure) {
268	            throw new IllegalStateException("could not read the reservations", failure);
269	        }
270	    }
271	
272	    private static Reservation read(ResultSet row) throws SQLException {
273	        Identification identification = Identifications.from(new IdentificationFields(
274	                row.getString("guest_cpf"),
275	                row.getString("company_cnpj"),
276	                row.getString("company_name"),
277	                row.getString("guest_passport"),
278	                row.getString("guest_country")));
279	        Guest guest = new Guest(row.getString("guest_name"), row.getString("guest_email"), identification);
280	        NewReservation request = new NewReservation(
281	                row.getInt("room_number"),
282	                guest,
283	                row.getDate("check_in").toLocalDate(),
284	                row.getDate("check_out").toLocalDate(),
285	                row.getInt("guests"),
286	                RatePlan.valueOf(row.getString("rate_plan")));
287	        Price price = new Price(
288	                row.getInt("nights"), row.getBigDecimal("subtotal"), row.getBigDecimal("discount"),
289	                row.getBigDecimal("total"));
290	        return new Reservation(
291	                row.getLong("id"),
292	                request,
293	                price,
294	                ReservationStatus.valueOf(row.getString("status")),
295	                row.getBigDecimal("amount_paid"),
296	                row.getBigDecimal("refund"));
297	    }
298	}
