 26	CREATE TABLE reservations (
 27	    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 28	    room_number integer NOT NULL REFERENCES rooms (number),
 29	    guest_name  text NOT NULL,
 30	    guest_email text NOT NULL,
 31	    guest_cpf   text NOT NULL,
 32	    check_in    date NOT NULL,
 33	    check_out   date NOT NULL,
 34	    guests      integer NOT NULL CHECK (guests >= 1),
 35	    rate_plan   text NOT NULL,
 36	    nights      integer NOT NULL,
 37	    subtotal    numeric(10, 2) NOT NULL,
 38	    discount    numeric(10, 2) NOT NULL,
 39	    total       numeric(10, 2) NOT NULL,
 40	    status      text NOT NULL,
 41	    amount_paid numeric(10, 2) NOT NULL,
 42	    refund      numeric(10, 2),
 43	    CHECK (check_out > check_in),
 44	    -- a room is never booked twice for the same night, even when two requests arrive at the same time
 45	    CONSTRAINT reservations_no_double_booking
 46	        EXCLUDE USING gist (room_number WITH =, daterange(check_in, check_out) WITH &&)
 47	        WHERE (status <> 'CANCELLED')
 48	);
 49	
 50	-- every message the inn sent, so the front desk can check what each guest received
 51	CREATE TABLE messages (
 52	    id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 53	    channel   text NOT NULL,
 54	    recipient text NOT NULL,
 55	    subject   text NOT NULL,
 56	    body      text NOT NULL
 57	);

