   112	    private static NewReservation readNewReservation(Context ctx) {
   113	        CreateReservationRequest body;
   114	        try {
   115	            body = ctx.bodyAsClass(CreateReservationRequest.class);
   116	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
   117	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
   118	        }
   119	        if (body == null
   120	                || body.roomNumber() == null
   121	                || isBlank(body.guestName())
   122	                || isBlank(body.guestEmail())
   123	                || body.checkIn() == null
   124	                || body.checkOut() == null
   125	                || body.guests() == null
   126	                || body.ratePlan() == null) {
   127	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   128	        }
   129	        Identification identification = Identifications.from(new IdentificationFields(
   130	                body.guestCpf(), body.companyCnpj(), body.companyName(), body.guestPassport(), body.guestCountry()));
   131	        Guest guest = new Guest(body.guestName(), body.guestEmail(), identification);
   132	        return new NewReservation(
   133	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
   134	    }
